using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class HomeControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly HomeController _controller;

        public HomeControllerTests()
        {
            _context = TestDbContextFactory.CreateWithData();
            _controller = new HomeController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsView()
        {
            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void About_ReturnsViewWithEnrollmentDateGroups()
        {
            var result = _controller.About() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
            Assert.NotEmpty(model);
        }

        [Fact]
        public void About_GroupsStudentsByEnrollmentDate()
        {
            var result = _controller.About() as ViewResult;
            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);

            // We have 3 students with dates: 2010-09-01, 2012-09-01, 2013-09-01
            Assert.Equal(3, model.Count);
            var totalStudents = model.Sum(g => g.StudentCount);
            Assert.Equal(3, totalStudents);
        }

        [Fact]
        public void About_EachGroupHasCorrectStudentCount()
        {
            var result = _controller.About() as ViewResult;
            var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);

            // Each date has exactly 1 student in our seed data
            Assert.All(model, group =>
            {
                Assert.Equal(1, group.StudentCount);
                Assert.NotNull(group.EnrollmentDate);
            });
        }

        [Fact]
        public void Contact_ReturnsViewWithMessage()
        {
            var result = _controller.Contact() as ViewResult;

            Assert.NotNull(result);
            Assert.Equal("Your contact page.", (string)_controller.ViewBag.Message);
        }

        [Fact]
        public void Error_ReturnsView()
        {
            var result = _controller.Error() as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Unauthorized_ReturnsViewWithMessage()
        {
            var result = _controller.Unauthorized() as ViewResult;

            Assert.NotNull(result);
            Assert.Equal("You don't have permission to access this resource.",
                (string)_controller.ViewBag.Message);
        }
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsView()
        {
            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void GetNotifications_ReturnsJsonWithSuccessTrue()
        {
            var result = _controller.GetNotifications();

            Assert.NotNull(result);
            var json = result.Value;
            Assert.NotNull(json);

            // Use reflection to check anonymous type properties
            var successProp = json.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(json));
        }

        [Fact]
        public void GetNotifications_ReturnsCountProperty()
        {
            var result = _controller.GetNotifications();
            var json = result.Value;

            var countProp = json.GetType().GetProperty("count");
            Assert.NotNull(countProp);
            var count = (int)countProp.GetValue(json);
            Assert.True(count >= 0);
        }

        [Fact]
        public void MarkAsRead_ReturnsJsonWithSuccessTrue()
        {
            var result = _controller.MarkAsRead(1);

            Assert.NotNull(result);
            var json = result.Value;
            Assert.NotNull(json);

            var successProp = json.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(json));
        }

        [Fact]
        public void MarkAsRead_WithAnyId_ReturnsSuccess()
        {
            // MarkAsRead is a no-op in the in-memory implementation
            var result = _controller.MarkAsRead(999);
            var json = result.Value;

            var successProp = json.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(json));
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;
using System;
using System.Collections.Generic;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain any leftover notifications from the static queue (shared across tests)
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain after test to avoid polluting other tests
            while (_service.ReceiveNotification() != null) { }
            _service.Dispose();
        }

        // --- SendNotification (4-param overload) ---

        [Fact]
        public void SendNotification_WithoutDisplayName_EnqueuesNotification()
        {
            _service.SendNotification("Student", "1", EntityOperation.CREATE, "admin");

            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_GeneratesMessageWithId()
        {
            _service.SendNotification("Course", "42", EntityOperation.UPDATE, "user1");

            var notification = _service.ReceiveNotification();
            Assert.Contains("Course (ID: 42)", notification.Message);
            Assert.Contains("has been updated", notification.Message);
        }

        // --- SendNotification (5-param overload) ---

        [Fact]
        public void SendNotification_WithDisplayName_GeneratesMessageWithName()
        {
            _service.SendNotification("Student", "5", "John Doe", EntityOperation.CREATE, "admin");

            var notification = _service.ReceiveNotification();
            Assert.Contains("Student 'John Doe'", notification.Message);
            Assert.Contains("has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_GeneratesDeleteMessage()
        {
            _service.SendNotification("Department", "3", "Engineering", EntityOperation.DELETE, "admin");

            var notification = _service.ReceiveNotification();
            Assert.Contains("Department 'Engineering'", notification.Message);
            Assert.Contains("has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_UpdateOperation_GeneratesUpdateMessage()
        {
            _service.SendNotification("Instructor", "7", "Jane Smith", EntityOperation.UPDATE, "admin");

            var notification = _service.ReceiveNotification();
            Assert.Contains("Instructor 'Jane Smith'", notification.Message);
            Assert.Contains("has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToCurrentTime()
        {
            var before = DateTime.Now.AddSeconds(-1);
            _service.SendNotification("Student", "1", EntityOperation.CREATE);
            var after = DateTime.Now.AddSeconds(1);

            var notification = _service.ReceiveNotification();
            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            _service.SendNotification("Student", "1", EntityOperation.CREATE, null);

            var notification = _service.ReceiveNotification();
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_NoUserNameParam_DefaultsToSystem()
        {
            _service.SendNotification("Student", "1", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsIsReadToFalse()
        {
            _service.SendNotification("Student", "1", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();
            Assert.False(notification.IsRead);
        }

        // --- ReceiveNotification ---

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _service.ReceiveNotification();

            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleNotifications_ReturnsFIFO()
        {
            _service.SendNotification("A", "1", EntityOperation.CREATE);
            _service.SendNotification("B", "2", EntityOperation.UPDATE);
            _service.SendNotification("C", "3", EntityOperation.DELETE);

            var first = _service.ReceiveNotification();
            var second = _service.ReceiveNotification();
            var third = _service.ReceiveNotification();

            Assert.Equal("A", first.EntityType);
            Assert.Equal("B", second.EntityType);
            Assert.Equal("C", third.EntityType);
        }

        [Fact]
        public void ReceiveNotification_DequeuedNotificationRemovedFromQueue()
        {
            _service.SendNotification("X", "1", EntityOperation.CREATE);

            var first = _service.ReceiveNotification();
            var second = _service.ReceiveNotification();

            Assert.NotNull(first);
            Assert.Null(second);
        }

        // --- MarkAsRead ---

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op but should not throw
            var exception = Record.Exception(() => _service.MarkAsRead(1));
            Assert.Null(exception);
        }

        [Fact]
        public void MarkAsRead_WithAnyId_DoesNotThrow()
        {
            var exception = Record.Exception(() => _service.MarkAsRead(999));
            Assert.Null(exception);
        }

        // --- Dispose ---

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var exception = Record.Exception(() => service.Dispose());
            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_CanBeCalledMultipleTimes()
        {
            var service = new NotificationService();
            service.Dispose();
            var exception = Record.Exception(() => service.Dispose());
            Assert.Null(exception);
        }

        // --- Message generation for all operations ---

        [Fact]
        public void SendNotification_NullDisplayName_UsesIdInMessage()
        {
            _service.SendNotification("Student", "42", null, EntityOperation.CREATE, "admin");

            var notification = _service.ReceiveNotification();
            Assert.Contains("Student (ID: 42)", notification.Message);
        }

        [Fact]
        public void SendNotification_EmptyDisplayName_UsesIdInMessage()
        {
            _service.SendNotification("Student", "42", "", EntityOperation.CREATE, "admin");

            var notification = _service.ReceiveNotification();
            Assert.Contains("Student (ID: 42)", notification.Message);
        }

        [Fact]
        public void SendNotification_WhitespaceDisplayName_UsesIdInMessage()
        {
            _service.SendNotification("Student", "42", "   ", EntityOperation.CREATE, "admin");

            var notification = _service.ReceiveNotification();
            Assert.Contains("Student (ID: 42)", notification.Message);
        }

        // --- Notification property verification ---

        [Fact]
        public void SendNotification_AllPropertiesSetCorrectly()
        {
            _service.SendNotification("Department", "10", "Engineering", EntityOperation.UPDATE, "admin");

            var notification = _service.ReceiveNotification();
            Assert.Equal("Department", notification.EntityType);
            Assert.Equal("10", notification.EntityId);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.Contains("Department 'Engineering'", notification.Message);
            Assert.Contains("has been updated", notification.Message);
        }
    }
}

using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests : IDisposable
    {
        private readonly SchoolContext _context;

        public SchoolContextTests()
        {
            _context = TestDbContextFactory.Create();
        }

        public void Dispose()
        {
            _context.Dispose();
        }

        // --- DbSet availability ---

        [Fact]
        public void Context_HasStudentsDbSet()
        {
            Assert.NotNull(_context.Students);
        }

        [Fact]
        public void Context_HasCoursesDbSet()
        {
            Assert.NotNull(_context.Courses);
        }

        [Fact]
        public void Context_HasDepartmentsDbSet()
        {
            Assert.NotNull(_context.Departments);
        }

        [Fact]
        public void Context_HasEnrollmentsDbSet()
        {
            Assert.NotNull(_context.Enrollments);
        }

        [Fact]
        public void Context_HasInstructorsDbSet()
        {
            Assert.NotNull(_context.Instructors);
        }

        [Fact]
        public void Context_HasOfficeAssignmentsDbSet()
        {
            Assert.NotNull(_context.OfficeAssignments);
        }

        [Fact]
        public void Context_HasCourseAssignmentsDbSet()
        {
            Assert.NotNull(_context.CourseAssignments);
        }

        [Fact]
        public void Context_HasNotificationsDbSet()
        {
            Assert.NotNull(_context.Notifications);
        }

        [Fact]
        public void Context_HasPeopleDbSet()
        {
            Assert.NotNull(_context.People);
        }

        // --- CRUD operations on Students ---

        [Fact]
        public void Students_CanAddAndRetrieve()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };

            _context.Students.Add(student);
            _context.SaveChanges();

            var retrieved = _context.Students.Find(student.ID);
            Assert.NotNull(retrieved);
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal("Student", retrieved.LastName);
            Assert.Equal(new DateTime(2023, 1, 1), retrieved.EnrollmentDate);
        }

        [Fact]
        public void Students_CanUpdate()
        {
            var student = new Student
            {
                FirstMidName = "Old",
                LastName = "Name",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };
            _context.Students.Add(student);
            _context.SaveChanges();

            student.FirstMidName = "New";
            student.LastName = "Updated";
            _context.SaveChanges();

            var updated = _context.Students.Find(student.ID);
            Assert.Equal("New", updated.FirstMidName);
            Assert.Equal("Updated", updated.LastName);
        }

        [Fact]
        public void Students_CanDelete()
        {
            var student = new Student
            {
                FirstMidName = "Delete",
                LastName = "Me",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };
            _context.Students.Add(student);
            _context.SaveChanges();
            var id = student.ID;

            _context.Students.Remove(student);
            _context.SaveChanges();

            Assert.Null(_context.Students.Find(id));
        }

        // --- CRUD operations on Courses ---

        [Fact]
        public void Courses_CanAddWithDepartmentRelationship()
        {
            var dept = new Department
            {
                Name = "TestDept",
                Budget = 50000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 9001,
                Title = "TestCourse",
                Credits = 4,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var retrieved = _context.Courses.Include(c => c.Department)
                .First(c => c.CourseID == 9001);
            Assert.Equal("TestCourse", retrieved.Title);
            Assert.Equal(4, retrieved.Credits);
            Assert.Equal(dept.DepartmentID, retrieved.DepartmentID);
        }

        // --- Enrollment relationships ---

        [Fact]
        public void Enrollments_CanLinkStudentAndCourse()
        {
            var student = new Student
            {
                FirstMidName = "Enrolled",
                LastName = "Student",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };
            _context.Students.Add(student);

            var dept = new Department
            {
                Name = "Dept",
                Budget = 10000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 8001,
                Title = "Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var enrollment = new Enrollment
            {
                StudentID = student.ID,
                CourseID = course.CourseID,
                Grade = Grade.B
            };
            _context.Enrollments.Add(enrollment);
            _context.SaveChanges();

            var retrieved = _context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .First(e => e.EnrollmentID == enrollment.EnrollmentID);
            Assert.Equal(student.ID, retrieved.StudentID);
            Assert.Equal(course.CourseID, retrieved.CourseID);
            Assert.Equal(Grade.B, retrieved.Grade);
            Assert.Equal("Enrolled", retrieved.Student.FirstMidName);
            Assert.Equal("Course", retrieved.Course.Title);
        }

        // --- CourseAssignment composite key ---

        [Fact]
        public void CourseAssignments_UseCompositeKey()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Instructor",
                HireDate = new DateTime(2020, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            var dept = new Department
            {
                Name = "TestDept",
                Budget = 10000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 7001,
                Title = "Test",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var assignment = new CourseAssignment
            {
                CourseID = course.CourseID,
                InstructorID = instructor.ID
            };
            _context.CourseAssignments.Add(assignment);
            _context.SaveChanges();

            var retrieved = _context.CourseAssignments
                .Find(course.CourseID, instructor.ID);
            Assert.NotNull(retrieved);
            Assert.Equal(course.CourseID, retrieved.CourseID);
            Assert.Equal(instructor.ID, retrieved.InstructorID);
        }

        // --- OfficeAssignment one-to-one ---

        [Fact]
        public void OfficeAssignment_OneToOneWithInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Office",
                LastName = "Person",
                HireDate = new DateTime(2020, 1, 1),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var retrieved = _context.Instructors
                .Include(i => i.OfficeAssignment)
                .First(i => i.ID == instructor.ID);
            Assert.NotNull(retrieved.OfficeAssignment);
            Assert.Equal("Room 101", retrieved.OfficeAssignment.Location);
            Assert.Equal(instructor.ID, retrieved.OfficeAssignment.InstructorID);
        }

        // --- TPH inheritance ---

        [Fact]
        public void People_IncludesBothStudentsAndInstructors()
        {
            _context.Students.Add(new Student
            {
                FirstMidName = "S",
                LastName = "Student",
                EnrollmentDate = new DateTime(2023, 1, 1)
            });
            _context.Instructors.Add(new Instructor
            {
                FirstMidName = "I",
                LastName = "Instructor",
                HireDate = new DateTime(2020, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            });
            _context.SaveChanges();

            var people = _context.People.ToList();
            Assert.True(people.Count >= 2);
            Assert.Contains(people, p => p is Student);
            Assert.Contains(people, p => p is Instructor);
        }

        // --- Notification CRUD ---

        [Fact]
        public void Notifications_CanAddAndRetrieve()
        {
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test message",
                CreatedAt = DateTime.Now,
                CreatedBy = "admin",
                IsRead = false
            };
            _context.Notifications.Add(notification);
            _context.SaveChanges();

            var retrieved = _context.Notifications.Find(notification.Id);
            Assert.NotNull(retrieved);
            Assert.Equal("Student", retrieved.EntityType);
            Assert.Equal("1", retrieved.EntityId);
            Assert.Equal("CREATE", retrieved.Operation);
            Assert.Equal("Test message", retrieved.Message);
            Assert.Equal("admin", retrieved.CreatedBy);
            Assert.False(retrieved.IsRead);
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using System;
using System.Collections.Generic;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class ModelTests
    {
        // --- Person / FullName ---

        [Fact]
        public void Person_FullName_ReturnsLastNameCommaFirstName()
        {
            var student = new Student
            {
                FirstMidName = "Carson",
                LastName = "Alexander",
                EnrollmentDate = DateTime.Now
            };

            Assert.Equal("Alexander, Carson", student.FullName);
        }

        [Fact]
        public void Instructor_FullName_ReturnsLastNameCommaFirstName()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = DateTime.Now,
                CourseAssignments = new List<CourseAssignment>()
            };

            Assert.Equal("Abercrombie, Kim", instructor.FullName);
        }

        // --- Student ---

        [Fact]
        public void Student_CanSetAndGetAllProperties()
        {
            var date = new DateTime(2023, 9, 1);
            var student = new Student
            {
                ID = 1,
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = date,
                Enrollments = new List<Enrollment>()
            };

            Assert.Equal(1, student.ID);
            Assert.Equal("Test", student.FirstMidName);
            Assert.Equal("Student", student.LastName);
            Assert.Equal(date, student.EnrollmentDate);
            Assert.NotNull(student.Enrollments);
            Assert.Empty(student.Enrollments);
        }

        [Fact]
        public void Student_InheritsFromPerson()
        {
            var student = new Student
            {
                FirstMidName = "A",
                LastName = "B",
                EnrollmentDate = DateTime.Now
            };

            Assert.IsAssignableFrom<Person>(student);
        }

        // --- Instructor ---

        [Fact]
        public void Instructor_CanSetAndGetAllProperties()
        {
            var date = new DateTime(2020, 1, 1);
            var instructor = new Instructor
            {
                ID = 2,
                FirstMidName = "Jane",
                LastName = "Doe",
                HireDate = date,
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { Location = "Room 5" }
            };

            Assert.Equal(2, instructor.ID);
            Assert.Equal("Jane", instructor.FirstMidName);
            Assert.Equal("Doe", instructor.LastName);
            Assert.Equal(date, instructor.HireDate);
            Assert.NotNull(instructor.CourseAssignments);
            Assert.NotNull(instructor.OfficeAssignment);
            Assert.Equal("Room 5", instructor.OfficeAssignment.Location);
        }

        [Fact]
        public void Instructor_InheritsFromPerson()
        {
            var instructor = new Instructor
            {
                FirstMidName = "A",
                LastName = "B",
                HireDate = DateTime.Now,
                CourseAssignments = new List<CourseAssignment>()
            };

            Assert.IsAssignableFrom<Person>(instructor);
        }

        // --- Course ---

        [Fact]
        public void Course_CanSetAndGetAllProperties()
        {
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/uploads/test.jpg",
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };

            Assert.Equal(1050, course.CourseID);
            Assert.Equal("Chemistry", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
            Assert.Equal("/uploads/test.jpg", course.TeachingMaterialImagePath);
        }

        [Fact]
        public void Course_TeachingMaterialImagePath_CanBeNull()
        {
            var course = new Course
            {
                CourseID = 100,
                Title = "Test",
                Credits = 1
            };

            Assert.Null(course.TeachingMaterialImagePath);
        }

        // --- Department ---

        [Fact]
        public void Department_CanSetAndGetAllProperties()
        {
            var date = new DateTime(2007, 9, 1);
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "English",
                Budget = 350000,
                StartDate = date,
                InstructorID = 5,
                RowVersion = new byte[] { 1, 2, 3 },
                Courses = new List<Course>()
            };

            Assert.Equal(1, dept.DepartmentID);
            Assert.Equal("English", dept.Name);
            Assert.Equal(350000, dept.Budget);
            Assert.Equal(date, dept.StartDate);
            Assert.Equal(5, dept.InstructorID);
            Assert.Equal(new byte[] { 1, 2, 3 }, dept.RowVersion);
        }

        [Fact]
        public void Department_InstructorIdCanBeNull()
        {
            var dept = new Department
            {
                Name = "Test",
                Budget = 0,
                StartDate = DateTime.Now,
                InstructorID = null
            };

            Assert.Null(dept.InstructorID);
        }

        // --- Enrollment ---

        [Fact]
        public void Enrollment_CanSetAndGetAllProperties()
        {
            var enrollment = new Enrollment
