using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_ReturnsCorrectPageOfItems()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();

            var page = PaginatedList<int>.Create(items, 1, 10);

            Assert.Equal(10, page.Count);
            Assert.Equal(1, page[0]);
            Assert.Equal(10, page[9]);
        }

        [Fact]
        public void Create_SecondPage_ReturnsCorrectItems()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();

            var page = PaginatedList<int>.Create(items, 2, 10);

            Assert.Equal(10, page.Count);
            Assert.Equal(11, page[0]);
            Assert.Equal(20, page[9]);
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();

            var page = PaginatedList<int>.Create(items, 3, 10);

            Assert.Equal(5, page.Count);
            Assert.Equal(21, page[0]);
            Assert.Equal(25, page[4]);
        }

        [Fact]
        public void PageIndex_IsSetCorrectly()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();

            var page = PaginatedList<int>.Create(items, 2, 10);

            Assert.Equal(2, page.PageIndex);
        }

        [Fact]
        public void TotalPages_CalculatedCorrectly()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();

            var page = PaginatedList<int>.Create(items, 1, 10);

            Assert.Equal(3, page.TotalPages);
        }

        [Fact]
        public void TotalPages_ExactDivision_CalculatedCorrectly()
        {
            var items = Enumerable.Range(1, 20).AsQueryable();

            var page = PaginatedList<int>.Create(items, 1, 10);

            Assert.Equal(2, page.TotalPages);
        }

        [Fact]
        public void TotalPages_SinglePage_IsOne()
        {
            var items = Enumerable.Range(1, 5).AsQueryable();

            var page = PaginatedList<int>.Create(items, 1, 10);

            Assert.Equal(1, page.TotalPages);
        }

        [Fact]
        public void HasPreviousPage_FirstPage_IsFalse()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();

            var page = PaginatedList<int>.Create(items, 1, 10);

            Assert.False(page.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_IsTrue()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();

            var page = PaginatedList<int>.Create(items, 2, 10);

            Assert.True(page.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_FirstPage_IsTrue()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();

            var page = PaginatedList<int>.Create(items, 1, 10);

            Assert.True(page.HasNextPage);
        }

        [Fact]
        public void HasNextPage_LastPage_IsFalse()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();

            var page = PaginatedList<int>.Create(items, 3, 10);

            Assert.False(page.HasNextPage);
        }

        [Fact]
        public void HasNextPage_MiddlePage_IsTrue()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();

            var page = PaginatedList<int>.Create(items, 2, 10);

            Assert.True(page.HasNextPage);
        }

        [Fact]
        public void Constructor_SetsPropertiesCorrectly()
        {
            var items = new List<string> { "a", "b", "c" };

            var page = new PaginatedList<string>(items, 10, 2, 5);

            Assert.Equal(3, page.Count);
            Assert.Equal(2, page.PageIndex);
            Assert.Equal(2, page.TotalPages); // ceil(10/5) = 2
            Assert.Equal("a", page[0]);
            Assert.Equal("b", page[1]);
            Assert.Equal("c", page[2]);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var items = Enumerable.Empty<int>().AsQueryable();

            var page = PaginatedList<int>.Create(items, 1, 10);

            Assert.Empty(page);
            Assert.Equal(0, page.TotalPages);
            Assert.False(page.HasPreviousPage);
            Assert.False(page.HasNextPage);
        }

        [Fact]
        public void Create_SingleItem_ReturnsOneItemOnePage()
        {
            var items = new[] { 42 }.AsQueryable();

            var page = PaginatedList<int>.Create(items, 1, 10);

            Assert.Single(page);
            Assert.Equal(42, page[0]);
            Assert.Equal(1, page.TotalPages);
            Assert.Equal(1, page.PageIndex);
        }
    }
}

