namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_EmptyDatabase_SeedsStudents()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsInstructors()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(5, context.Instructors.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsDepartments()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(4, context.Departments.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourses()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(7, context.Courses.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsEnrollments()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(11, context.Enrollments.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(3, context.OfficeAssignments.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourseAssignments()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.CourseAssignments.Count());
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicateData()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);
            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
            Assert.Equal(5, context.Instructors.Count());
            Assert.Equal(4, context.Departments.Count());
        }

        [Fact]
        public void Initialize_SeededStudentNames_AreCorrect()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var lastNames = context.Students.Select(s => s.LastName).OrderBy(n => n).ToList();
            Assert.Contains("Alexander", lastNames);
            Assert.Contains("Alonso", lastNames);
            Assert.Contains("Anand", lastNames);
            Assert.Contains("Barzdukas", lastNames);
            Assert.Contains("Li", lastNames);
            Assert.Contains("Justice", lastNames);
            Assert.Contains("Norman", lastNames);
            Assert.Contains("Olivetto", lastNames);
        }

        [Fact]
        public void Initialize_SeededDepartments_HaveCorrectBudgets()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var english = context.Departments.First(d => d.Name == "English");
            Assert.Equal(350000, english.Budget);

            var math = context.Departments.First(d => d.Name == "Mathematics");
            Assert.Equal(100000, math.Budget);
        }

        [Fact]
        public void Initialize_SeededCourses_HaveCorrectCredits()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var chemistry = context.Courses.First(c => c.Title == "Chemistry");
            Assert.Equal(3, chemistry.Credits);

            var calculus = context.Courses.First(c => c.Title == "Calculus");
            Assert.Equal(4, calculus.Credits);
        }
    }
}

